'use strict';
const fs=require('node:fs'), assert=require('node:assert/strict');
const css=fs.readFileSync('assets/arcade-candy-world-v157.css','utf8');
const all=fs.readFileSync('assets/all-tabs-v150.css','utf8');
const menu=fs.readFileSync('assets/game-menu-v91.js','utf8');
const version=JSON.parse(fs.readFileSync('app-version.json','utf8')).version;
const selector='html.arcade-candy-world-v157[data-lineup="all"] #tabs>.tab-slot>.all-tab-frame-overlay';
const escaped=selector.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const re=new RegExp(escaped+'\\s*\\{([^}]*)\\}');
const match=css.match(re);
assert(match,'nine-tab decorated overlay exists');
assert.match(match[1],/z-index:1!important/,'decoration must sit below game content');
assert.doesNotMatch(match[1],/z-index:80!important/,'opaque decoration cannot hide game tabs');
assert.match(match[1],/background:var\\(--all-tab-frame\\)/,'game-specific frame image retained');
assert.match(all,/#tabs>.tab-slot>.tab\\{\\s*z-index:30!important/,'live preview above decoration');
assert.match(all,/#tabs>.tab-slot>.tab-bets,[\\s\\S]*?z-index:40!important/,'reach and BET above decoration');
assert.match(menu,/arcade-candy-world-v157\\.css\\?v=233/,'mobile browser must reload corrected CSS');
assert.match(version,/v233-tab-visibility/,'installed clients must refresh');
console.log('NINE_TAB_VISIBILITY_V233_PASS');
